import numpy as np
from scipy.optimize import minimize_scalar

def g(x):
    if x <= 0 or x >= 1:
        return 0
    return 4*x + 4*(1-x)**(1/3) * x**(2/3)

# We want to maximize g(x), so minimize -g(x)
res = minimize_scalar(lambda x: -g(x), bounds=(0, 1), method='bounded')
print(f"Maximum g(x) at x = {res.x} is {g(res.x)}")

# Check some specific values of x
for x in np.linspace(0, 1, 100):
    val = g(x)
    if val > g(res.x):
        print(f"Better value at x={x}: {val}")

import numpy as np
from scipy.optimize import fsolve

def g_prime(x):
    return 4 + 4 * (2 - 3*x) / (3 * x**(1/3) * (1-x)**(2/3))

# Find roots of g_prime(x) = 0 in (0, 1)
roots = []
for i in np.linspace(0.1, 0.9, 10):
    root = fsolve(g_prime, i)[0]
    if 0 < root < 1:
        roots.append(root)

print(f"Roots: {np.unique(np.round(roots, 10))}")
